import React, { useEffect, useState, useRef } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { ArrowLeft } from "lucide-react";
import "prismjs/themes/prism-okaidia.css";
import Prism from "prismjs";
import "prismjs/components/prism-python";
import "prismjs/components/prism-c";
import "prismjs/components/prism-cpp";
import "prismjs/components/prism-java";
import "prismjs/components/prism-json";
import "prismjs/components/prism-markdown";
import "prismjs/components/prism-yaml";
import "prismjs/components/prism-javascript";
import "prismjs/components/prism-typescript";
import "prismjs/components/prism-css";
import "./App.css";
import ParticipantNavbar from "./components/ParticipantNavbar";
import { Star } from "lucide-react";

function TaskDetailPage() {
    const { taskId } = useParams();
    const navigate = useNavigate();
    const [selectedArtifacts, setSelectedArtifacts] = useState([]);
    const storedUser = JSON.parse(localStorage.getItem("user"));
    const username = storedUser?.username || "Participant";

    const [task, setTask] = useState(null);
    const [loading, setLoading] = useState(true);
    const [textContents, setTextContents] = useState({});
    const [hover, setHover] = useState(null);
    const [selectedCard, setSelectedCard] = useState(null);
    const [activeAction, setActiveAction] = useState(null);
    const [activeArtifact, setActiveArtifact] = useState(null);
    const [compareHover, setCompareHover] = useState(null);

    const fieldCodes = ["A", "B", "C", "D"];
    const [activeField, setActiveField] = useState("A"); // Şimdilik kullanılmıyor ama dursun

    const [commentsByField, setCommentsByField] = useState({});
    const [newCommentText, setNewCommentText] = useState("");
    const [imageUrls, setImageUrls] = useState({});
    const [pdfUrls, setPdfUrls] = useState({});

    const gridRef = useRef(null);

    // 🔥 REPORT STATE
    const [reportContext, setReportContext] = useState(null);
    // { targetType: "ARTIFACT" | "PARTICIPANT", artifact, reportedUsername? }

    const [reportReason, setReportReason] = useState("");
    const [reportDescription, setReportDescription] = useState("");
    const [reportSubmitting, setReportSubmitting] = useState(false);
    const [reportError, setReportError] = useState("");
    const [reportSuccess, setReportSuccess] = useState("");

    //reply comment
    const [replyTarget, setReplyTarget] = useState(null);
    const [replyText, setReplyText] = useState("");
    const [openReplies, setOpenReplies] = useState({});

    //edit or delete comment
    const [editingCommentId, setEditingCommentId] = useState(null);
    const [editText, setEditText] = useState("");

    //evaluation
    const [evaluation, setEvaluation] = useState({});
    const [evaluationAnswers, setEvaluationAnswers] = useState({});

    //custom criterias
    const [customCriteria, setCustomCriteria] = useState({});

    const updateCustomCriteria = (fieldCode, criterionId, value) => {
        setCustomCriteria(prev => ({
            ...prev,
            [fieldCode]: {
                ...(prev[fieldCode] || {}),
                [criterionId]: value
            }
        }));
    };

    const updateEval = (fieldCode, patch) => {
        setEvaluationAnswers((prev) => ({
            ...prev,
            [fieldCode]: { ...(prev[fieldCode] || {}), ...patch }
        }));
    };

    const EvalOption = ({ label, icon, selected, onClick }) => {
        return (
            <button
                onClick={onClick}
                style={{
                    ...styles.neonEvalBtn,
                    ...(selected ? styles.neonEvalBtnSelected : {}),
                    display: "flex",
                    alignItems: "center",
                    gap: "10px",
                }}
            >
                <span style={{ fontSize: "1.3rem" }}>{icon}</span>
                <span>{label}</span>
            </button>
        );
    };

    const getFileIcon = (filename) => {
        const ext = filename.split(".").pop().toLowerCase();

        switch (ext) {
            case "java":
                return "☕";
            case "cpp":
                return "⚙️";
            case "py":
                return "🐍";
            case "js":
                return "📜";
            case "ts":
                return "🟦";
            case "pdf":
                return "📕";
            case "txt":
                return "📄";
            default:
                return "📄";
        }
    };

    const getFileColor = (filename) => {
        const ext = filename.split(".").pop().toLowerCase();

        switch (ext) {
            case "java":
                return { bg: "rgba(244,114,182,0.15)", color: "#f472b6" };
            case "cpp":
                return { bg: "rgba(96,165,250,0.15)", color: "#60a5fa" };
            case "py":
                return { bg: "rgba(250,204,21,0.15)", color: "#fde047" };
            case "js":
                return { bg: "rgba(34,197,94,0.15)", color: "#4ade80" };
            case "ts":
                return { bg: "rgba(96,165,250,0.15)", color: "#3b82f6" };
            case "pdf":
                return { bg: "rgba(239,68,68,0.15)", color: "#f87171" };
            case "txt":
                return { bg: "rgba(156,163,175,0.15)", color: "#9ca3af" };
            default:
                return { bg: "rgba(156,163,175,0.15)", color: "#9ca3af" };
