                                        color: "#a5f3fc"
                                    }}
                                >
                                    Save
                                </button>
                                <button
                                    onClick={() => setEditingCommentId(null)}
                                    style={{
                                        marginLeft: "10px",
                                        marginTop: "6px",
                                        background: "rgba(255,255,255,0.1)",
                                        padding: "6px 12px",
                                        borderRadius: "8px",
