                        ) : (
                            <div style={{ whiteSpace: "pre-wrap" }}>
                                {c.deleted ? "[deleted]" : c.content}
                            </div>
                        )}

                        {/* Footer */}
                        <div
                            style={{
                                fontSize: "0.7rem",
                                opacity: 0.6,
                                marginTop: "6px",
                                textAlign: isMine ? "right" : "left",
                            }}
                        >
                            {new Date(c.createdAt).toLocaleString()}
                        </div>
                        {/* SEE REPLIES */}
                        {c.replies && c.replies.length > 0 && (
                            <button
                                onClick={() =>
                                    setOpenReplies(prev => ({
                                        ...prev,
                                        [c.id]: !prev[c.id]
                                    }))
                                }
                                style={{
                                    background: "none",
                                    border: "none",
                                    color: "#60a5fa",
                                    cursor: "pointer",
                                    fontSize: "0.8rem",
                                    marginTop: "4px"
                                }}
                            >
