    const setEvalField = (artifactId, key, value) => {
        setEvaluation(prev => ({
            ...prev,
            [artifactId]: {
                ...(prev[artifactId] || {}),
                [key]: value
            }
        }));
    };

    const dropdownStyle = {
        width: "100%",
        padding: "10px 12px",
        marginTop: "6px",
