        switch (task.studyType) {
            case "SNAPSHOT_TESTING":
                return renderSnapshotEvaluation(fieldCode);

            case "BUG_CATEGORIZATION":
                return renderBugEvaluation(fieldCode);

            case "SOLID_DETECTION":
                return renderSolidEvaluation(fieldCode);

            case "CODE_CLONE":
                return renderCloneEvaluation(fieldCode);

            default:
                return null;
        }
    };

    const renderSnapshotEvaluation = (fieldCode) => {
