        const opts = [
            { key: "colorChange", icon: "🎨", label: "Color Change" },
            { key: "layoutChange", icon: "📐", label: "Layout Shift" },
            { key: "textChange", icon: "🔤", label: "Text Change" },
            { key: "visibleDiff", icon: "👁️", label: "Visible Difference" },
            { key: "iconChange", icon: "🔧", label: "Icon Change" },
            { key: "positionChange", icon: "📍", label: "Position Change" },
            { key: "sizeChange", icon: "📏", label: "Size Change" },
            { key: "missingElement", icon: "❌", label: "Missing Element" },
            { key: "newElement", icon: "➕", label: "New UI Element" },
        ];

