        "DATABASE",
        "GUI",
        "PERFORMANCE",
        "PERMISSION_DEPRECATION",
        "SECURITY",
        "FUNCTIONAL",
        "TEST_CODE",
    ];

    const renderBugEvaluation = (fieldCode) => {
