            headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${token}`
            },
            body: JSON.stringify(body)
        });

        if (!res.ok) {
            alert("Error submitting custom criteria");
            return;
        }

        alert("Custom criteria submitted!");
    };

    useEffect(() => {
        Prism.highlightAll();
    }, [textContents]);

    useEffect(() => Prism.highlightAll(), [selectedArtifacts]);

    useEffect(() => {
        const token = localStorage.getItem("token");

        fetch(`http://localhost:8080/api/tasks/details/${taskId}`, {
            headers: {
                Authorization: `Bearer ${token}`,
            },
        })
            .then((res) => res.json())
            .then((data) => {
                setTask(data);
                setLoading(false);

                data.artifacts.forEach((f) => {

                    // === TEXT FILE ===
                    if (isTextFile(f.filename)) {
                        fetch(`http://localhost:8080/file/${f.id}`, {
                            headers: { Authorization: `Bearer ${token}` }
                        })
                            .then((res) => res.text())
                            .then((txt) =>
                                setTextContents((prev) => ({
                                    ...prev,
                                    [f.id]: txt,
                                }))
                            );
                    }

                    // === IMAGE FILE ===
                    if (isImage(f.filename)) {
                        fetch(`http://localhost:8080/file/${f.id}`, {
                            headers: { Authorization: `Bearer ${token}` }
                        })
                            .then((res) => res.blob())
                            .then((blob) => {
                                const url = URL.createObjectURL(blob);

                                setImageUrls((prev) => ({
                                    ...prev,
                                    [f.id]: url,
                                }));
                            });
                    }
                    if (isPdf(f.filename)) {
                        fetch(`http://localhost:8080/file/${f.id}`, {
                            headers: { Authorization: `Bearer ${token}` }
                        })
                            .then((res) => res.blob())
                            .then((blob) => {
                                const url = URL.createObjectURL(blob);

                                setPdfUrls((prev) => ({
                                    ...prev,
                                    [f.id]: url,
                                }));
                            });
                    }

                });

            })
            .catch((err) => console.error("Task fetch error:", err));
    }, [taskId]);

    useEffect(() => {
        if (selectedCard) {
            setTimeout(() => Prism.highlightAll(), 50);
        }
    }, [selectedCard]);

    useEffect(() => {
        if (!taskId) return;

        const token = localStorage.getItem("token");

        fieldCodes.forEach((field) => {
            fetch(
                `http://localhost:8080/api/comments/task/${taskId}/field/${field}`,
                {
                    headers: { Authorization: `Bearer ${token}` },
                }
            )
                .then((res) => res.json())
                .then((data) => {
                    setCommentsByField((prev) => ({
                        ...prev,
                        [field]: data,
                    }));
                })
                .catch((err) =>
                    console.error("Comments fetch error:", err)
                );
        });
    }, [taskId]);

    if (loading) return <div style={styles.loading}>Loading...</div>;
    if (!task) return <div style={styles.loading}>Task not found</div>;

    const artifacts = task.artifacts;

    return (
        <div style={styles.container}>
            <ParticipantNavbar username={username} />

            <h2 style={styles.title}>{task.questionText}</h2>
            <p style={styles.subtitle}>{task.description}</p>

            {/* ======================================
                TAB BAR (dosya isimleri)
               ====================================== */}
            <div style={styles.tabBar}>
                {artifacts.map((f, index) => (
                    <button
                        key={f.id}
                        style={styles.tabBtn}
                        onClick={() => scrollToIndex(index)}
                    >
                        {f.filename}
                    </button>
                ))}
            </div>

            {/* ======================================
                GRID — yatay scroll + snap
               ====================================== */}
            <div id="artifact-grid" ref={gridRef} style={styles.grid}>
                {artifacts.map((f) => {
                    const fileUrl = `http://localhost:8080${f.filepath}`;

                    return (

                        <div
                            key={f.id}
                            style={{
                                ...styles.card,
                                ...(hover === f.id ? styles.cardHover : {}),
                                ...(selectedArtifacts.includes(f.id)
                                    ? {
                                        border: "1px solid #60a5fa",
                                        boxShadow:
                                            "0 0 20px rgba(96,165,250,0.45)",
                                    }
                                    : {}),
                            }}
                            onMouseEnter={() => setHover(f.id)}
                            onMouseLeave={() => setHover(null)}
                            onClick={() => toggleSelect(f.id)}
                        >
                            <div
                                style={{
                                    display: "flex",
                                    alignItems: "center",
                                    gap: "10px",
                                }}
                            >
                                <div
                                    style={{
                                        background:
                                        getFileColor(f.filename).bg,
                                        color: getFileColor(f.filename).color,
                                        padding: "6px 10px",
                                        borderRadius: "10px",
                                        fontSize: "1.2rem",
                                    }}
                                >
                                    {getFileIcon(f.filename)}
                                </div>

                                <h3 style={styles.filename}>
                                    {f.filename}
                                </h3>
                            </div>

                            {isTextFile(f.filename) && (
                                <pre style={styles.snippetBox}>
                                    {textContents[f.id]
                                        ?.split("\n")
                                        .slice(0, 4)
                                        .join("\n") || "Loading..."}
                                </pre>
                            )}

                            {isImage(f.filename) && (
                                <img
                                    src={imageUrls[f.id]}
                                    alt={f.filename}
                                    style={styles.thumbnail}
                                />
                            )}

                            {!isTextFile(f.filename) &&
                                !isImage(f.filename) && (
                                    <p style={styles.fileNotice}>
                                        Click to open details →
                                    </p>
                                )}

                            <div
                                style={{
                                    display: "flex",
                                    justifyContent: "space-between",
                                    marginTop: 10,
                                }}
                            >
                                <div
                                    style={{
                                        ...styles.selectBadge,
                                        ...(selectedArtifacts.includes(f.id)
                                            ? styles.selectBadgeActive
                                            : styles.selectBadgeInactive),
                                    }}
                                >
                                    {selectedArtifacts.includes(f.id)
                                        ? "Selected"
                                        : "Select"}
                                </div>
                                <button
                                    style={styles.viewBtn}
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        setSelectedCard(f);
                                    }}
                                >
                                    View
                                </button>
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* ======================================
                COMPARISON AREA
               ====================================== */}
            {selectedArtifacts.length > 0 && (
                <div style={styles.comparisonArea}>
                    {selectedArtifacts.map((id) => {
                        const f = artifacts.find((x) => x.id === id);
                        const index = artifacts.findIndex(x => x.id === id);   // ⭐ YENİ
                        const code = task.responseFields[index];
                        if (!f) return null;

                        return (
                            <div
                                key={id}
                                style={{
                                    ...styles.compareCard,
                                    width:
                                        selectedArtifacts.length === 1
                                            ? "85vw"
                                            : selectedArtifacts.length === 2
                                                ? "40vw"
                                                : "30vw",
                                }}
                                onMouseEnter={() => setCompareHover(id)}
                                onMouseLeave={() => setCompareHover(null)}
                            >
                                {/* FLOATING ACTION BAR — SAĞ ÜST */}
                                <div
                                    style={{
                                        ...styles.floatingBar,
                                        opacity:
                                            compareHover === f.id ? 1 : 0,
                                    }}
                                    onMouseEnter={() => setHover(f.id)}
                                    onMouseLeave={() => setHover(null)}
                                >
                                    <button
                                        style={styles.floatBtn}
                                        onClick={() => {
                                            setActiveArtifact(f);
                                            setActiveAction("comment");
                                        }}
                                    >
                                        💬
                                    </button>
                                    <button
                                        style={styles.floatBtn}
                                        onClick={() => {
                                            setActiveArtifact(f);
                                            setActiveAction("note");
                                        }}
                                    >
                                        📝
                                    </button>
                                    <button
                                        style={styles.floatBtn}
                                        onClick={() => {
                                            setActiveArtifact(f);
                                            setActiveAction("annotation");
                                        }}
                                    >
                                        ✨
                                    </button>
                                    <button
                                        style={styles.floatBtn}
                                        onClick={() => {
                                            setActiveArtifact(f);
                                            setReportContext({
                                                targetType: "ARTIFACT",
                                                artifact: f,
                                                reportedUsername: null,
                                            });
                                            setReportReason("");
                                            setReportDescription("");
                                            setReportError("");
                                            setReportSuccess("");
                                            setActiveAction("report");
                                        }}
                                    >
                                        ⚠️
                                    </button>
                                </div>

                                {/* HEADER */}
                                <div
                                    style={{
                                        display: "flex",
                                        alignItems: "center",
                                        gap: "10px",
                                    }}
                                >
                                    <div
                                        style={{
                                            background:
                                            getFileColor(f.filename).bg,
                                            color: getFileColor(f.filename)
                                                .color,
                                            padding: "6px 10px",
                                            borderRadius: "10px",
                                            fontSize: "1.2rem",
                                        }}
                                    >
                                        {getFileIcon(f.filename)}
                                    </div>

                                    <h3 style={styles.compareTitle}>
                                        {f.filename}
                                    </h3>
                                </div>

                                {/* CONTENT */}
                                {/* TEXT FILE */}
                                {isTextFile(f.filename) && (
                                    <pre
                                        style={{
                                            ...styles.compareText,
                                            flexShrink: 0,
                                            height: "350px",
                                            overflowY: "auto",
                                        }}
                                    >
        <code className={`language-${detectLanguage(f.filename)}`}>
            {textContents[f.id] || "Loading..."}
        </code>
    </pre>
                                )}

                                {/* IMAGE FILE */}
                                {isImage(f.filename) && (
                                    <img
                                        src={imageUrls[f.id]}
                                        alt={f.filename}
                                        style={styles.compareImage}
                                    />
                                )}

                                {/* PDF FILE */}
                                {isPdf(f.filename) && (
                                    <embed
                                        src={pdfUrls[f.id]}
                                        type="application/pdf"
                                        style={{
                                            width: "100%",
                                            height: "400px",
                                            borderRadius: "10px",
                                        }}
                                    />
                                )}

                                {/* OTHER FILE TYPES */}
                                {!isTextFile(f.filename) &&
                                    !isImage(f.filename) &&
                                    !isPdf(f.filename) && (
                                        <a
                                            href={`http://localhost:8080/file/${f.id}`}
                                            target="_blank"
                                            rel="noreferrer"
                                            style={styles.openLink}
                                        >
                                            ➜ Open file in new tab
                                        </a>
                                    )}
                                {/* === EVALUATION (artifact-specific) === */}
                                <FloatingEvaluation
                                    fieldCode={code}
                                    criteria={task.evaluationCriteria}
                                    values={evaluationAnswers[code] || {}}
                                    onChange={(criterionId, value) => {
                                        updateCustomCriteria(code, criterionId, value);

                                        setEvaluationAnswers(prev => ({
                                            ...prev,
                                            [code]: {
                                                ...(prev[code] || {}),
                                                [criterionId]: value
                                            }
                                        }));
                                    }}
                                />
                                <button
                                    style={styles.primaryBtn}
                                    onClick={submitCustomCriteria}
                                >
                                    Submit Custom Criteria
                                </button>
                                {/* === COMMENT SECTION (artifact-specific) === */}
                                {(() => {
                                    const code = task.responseFields[artifacts.indexOf(f)];

                                    return (
                                        <div style={{ marginTop: "25px", width: "100%" }}>
                                            <h4 style={{ textAlign: "left", marginBottom: "8px" }}>
                                                Comments for field "{code}"
                                            </h4>
                                            {/* COMMENT LIST */}
                                            {(commentsByField[code] || []).map((c) =>
                                                renderCommentThread(c, code)
                                            )}
                                            {/* INPUT */}
                                            <textarea
                                                value={newCommentText[code] || ""}
                                                onChange={(e) =>
                                                    setNewCommentText((prev) => ({
                                                        ...prev,
                                                        [code]: e.target.value,
                                                    }))
                                                }
                                                placeholder={`Write a comment for field ${code}...`}
                                                style={{
                                                    width: "100%",
                                                    padding: "10px",
                                                    borderRadius: "8px",
                                                    background: "rgba(255,255,255,0.08)",
                                                    border: "1px solid rgba(255,255,255,0.2)",
                                                    color: "white",
                                                    marginTop: "10px",
                                                }}
                                            />

                                            <button
                                                onClick={() => submitComment(code)}
                                                style={{
                                                    marginTop: "8px",
                                                    background: "rgba(56,189,248,0.35)",
                                                    padding: "10px 16px",
                                                    borderRadius: "8px",
                                                    color: "#a5f3fc",
                                                    border: "1px solid rgba(56,189,248,0.6)",
                                                    cursor: "pointer",
                                                }}
                                            >
                                                Send
                                            </button>
                                        </div>
                                    );
                                })()}

                            </div>
                        );
                    })}
                </div>
            )}
            {/* ======== GLOBAL EVALUATION — TEK KEZ ======== */}
            <div style={{ marginTop: "40px", width: "90%", marginLeft: "auto", marginRight: "auto" }}>
                {renderEvaluationSection("GLOBAL")}
            </div>
            <button
                style={styles.primaryBtn}
                onClick={submitEvaluation}
            >
                Submit Evaluation
            </button>

            {/* FULLSCREEN MODAL (View butonundan açılan) */}
            {selectedCard && (
                <div
                    style={styles.modalOverlay}
                    onClick={() => setSelectedCard(null)}
                >
                    <div
                        style={styles.modalCard}
                        onClick={(e) => e.stopPropagation()}
                    >
                        <div style={styles.modalHeader}>
                            <h2 style={styles.modalTitle}>
                                {selectedCard.filename}
                            </h2>
                            <button
                                style={styles.closeBtn}
                                onClick={() => setSelectedCard(null)}
                            >
                                ✕
                            </button>
                        </div>

                        {isTextFile(selectedCard.filename) && (
                            <pre style={styles.modalTextBox}>
                                <code
                                    className={`language-${detectLanguage(
                                        selectedCard.filename
                                    )}`}
                                >
                                    {textContents[selectedCard.id]}
                                </code>
                            </pre>
                        )}

                        {isImage(selectedCard.filename) && (
                            <img
                                src={imageUrls[selectedCard.id]}
                                alt={selectedCard.filename}
                                style={styles.modalImage}
                            />
                        )}

                        {isPdf(selectedCard.filename) && (
                            <embed
                                src={pdfUrls[selectedCard.id]}
                                type="application/pdf"
                                style={{
                                    width: "100%",
                                    height: "80vh",
                                    borderRadius: "10px",
                                }}
                            />
                        )}

                        {!isTextFile(selectedCard.filename) &&
                            !isImage(selectedCard.filename) && (
                                <a
                                    href={`http://localhost:8080/file/${selectedCard.id}`}
                                    target="_blank"
                                    rel="noreferrer"
                                    style={styles.openLink}
                                >
                                    ➜ Open file in new tab
                                </a>
                            )}
                    </div>
                </div>
            )}

            {/* REPORT MODAL (⚠️) */}
            {activeAction === "report" && reportContext && (
                <div
                    style={styles.modalOverlay}
                    onClick={() => {
                        setActiveAction(null);
                        setReportContext(null);
                        setReportReason("");
                        setReportDescription("");
                        setReportError("");
                        setReportSuccess("");
                    }}
                >
                    <div
                        style={styles.modalCard}
                        onClick={(e) => e.stopPropagation()}
                    >
                        <div style={styles.modalHeader}>
                            <h2 style={styles.modalTitle}>
                                {reportContext.targetType === "ARTIFACT"
                                    ? `Report Artifact: ${reportContext.artifact?.filename}`
                                    : `Report Participant: ${reportContext.reportedUsername}`}
                            </h2>
                            <button
                                style={styles.closeBtn}
                                onClick={() => {
                                    setActiveAction(null);
                                    setReportContext(null);
                                    setReportReason("");
                                    setReportDescription("");
                                    setReportError("");
                                    setReportSuccess("");
                                }}
                            >
                                ✕
                            </button>
                        </div>

                        {/* Reason */}
                        <div style={{ marginBottom: "14px" }}>
                            <label
                                style={{
                                    display: "block",
                                    marginBottom: "6px",
                                    fontSize: "0.9rem",
                                    opacity: 0.9,
                                }}
                            >
                                Reason *
                            </label>
                            <select
                                value={reportReason}
                                onChange={(e) => setReportReason(e.target.value)}
                                style={{
                                    width: "100%",
                                    padding: "10px 12px",
                                    borderRadius: "10px",
                                    border: "1px solid rgba(255,255,255,0.25)",
                                    background: "rgba(0,0,0,0.35)",
                                    color: "white",
                                }}
                            >
                                <option value="">Select a reason</option>
                                <option value="INAPPROPRIATE_CONTENT">
                                    Inappropriate / offensive content
                                </option>
                                <option value="HARASSMENT">
                                    Harassment or abuse
                                </option>
                                <option value="SPAM">
                                    Spam or irrelevant content
                                </option>
                                <option value="OTHER">
                                    Other
                                </option>
                            </select>
                        </div>

                        {/* Description */}
                        <div style={{ marginBottom: "14px" }}>
                            <label
                                style={{
                                    display: "block",
                                    marginBottom: "6px",
                                    fontSize: "0.9rem",
                                    opacity: 0.9,
                                }}
                            >
                                Description (please explain briefly) *
                            </label>
                            <textarea
                                value={reportDescription}
                                onChange={(e) =>
                                    setReportDescription(e.target.value)
                                }
                                rows={4}
                                style={{
                                    width: "100%",
                                    padding: "10px 12px",
                                    borderRadius: "10px",
                                    border: "1px solid rgba(255,255,255,0.25)",
                                    background: "rgba(0,0,0,0.35)",
                                    color: "white",
                                    resize: "vertical",
                                }}
                            />
                        </div>

                        {/* Error / Success */}
                        {reportError && (
                            <div
                                style={{
                                    marginBottom: "10px",
                                    color: "#fecaca",
                                    fontSize: "0.85rem",
                                }}
                            >
                                {reportError}
                            </div>
                        )}
                        {reportSuccess && (
                            <div
                                style={{
                                    marginBottom: "10px",
                                    color: "#bbf7d0",
                                    fontSize: "0.85rem",
                                }}
                            >
                                {reportSuccess}
                            </div>
                        )}

                        {/* Buttons */}
                        <div
                            style={{
                                display: "flex",
                                justifyContent: "flex-end",
                                gap: "10px",
                                marginTop: "10px",
                            }}
                        >
                            <button
                                style={styles.secondaryBtn}
                                onClick={() => {
                                    setActiveAction(null);
                                    setReportContext(null);
                                    setReportReason("");
                                    setReportDescription("");
                                    setReportError("");
                                    setReportSuccess("");
                                }}
                                disabled={reportSubmitting}
                            >
                                Cancel
                            </button>
                            <button
                                style={styles.primaryBtn}
                                onClick={submitReport}
                                disabled={reportSubmitting}
                            >
                                {reportSubmitting ? "Sending..." : "Submit report"}
                            </button>
                        </div>
                    </div>
                </div>
            )}

        </div>
    );
}

export default TaskDetailPage;

/* ---------------------------------------------------------
   ---------- HELPER FUNCTIONS
   --------------------------------------------------------- */

function isTextFile(name) {
    return name.match(
        /\.(txt|py|cpp|c|cs|java|js|ts|json|xml|html|css|md|yml|yaml)$/i
    );
}

function isImage(name) {
    return name.match(/\.(png|jpg|jpeg|gif)$/i);
}

function isPdf(name) {
    return name.toLowerCase().endsWith(".pdf");
}

function detectLanguage(filename) {
    const ext = filename.split(".").pop().toLowerCase();
    const map = {
        txt: "markup",
        py: "python",
        cpp: "cpp",
        c: "c",
        cs: "csharp",
        java: "java",
        js: "javascript",
        ts: "typescript",
        json: "json",
        xml: "xml",
        html: "html",
        css: "css",
        md: "markdown",
        yml: "yaml",
        yaml: "yaml",
    };
    return map[ext] || "markup";
}

function ModernRating({ value, onChange }) {
    return (
        <div style={{
            display: "flex",
            gap: 10,
            marginTop: 6,
            justifyContent: "flex-start"
        }}>
            {[1,2,3,4,5].map(n => (
                <Star
                    key={n}
                    size={26}
                    color={n <= value ? "#facc15" : "#444"}
                    fill={n <= value ? "#facc15" : "transparent"}
                    style={{
                        cursor: "pointer",
                        transition: "0.25s",
                    }}
                    onClick={() => onChange(n)}
                />
            ))}
        </div>
    );
}

function YesNoInput({ value, onChange }) {
    return (
        <div style={{ marginTop: 6 }}>
            <select
                value={value}
                onChange={(e) => onChange(e.target.value)}
                style={{
                    width: "100%",
                    padding: "10px",
                    borderRadius: "8px",
                    background: "rgba(255,255,255,0.08)",
                    border: "1px solid rgba(255,255,255,0.2)",
                    color: "white",
                }}
            >
                <option value="">Select…</option>
                <option value="YES">Yes</option>
                <option value="NO">No</option>
            </select>
