    );
}


function ModernNumericInput({ min, max, value, onChange }) {
    return (
        <input
            type="number"
            min={min}
            max={max}
            value={value}
            onChange={(e) => onChange(Number(e.target.value))}
            style={{
                width: "100%",
                padding: "10px 14px",
                marginTop: "6px",
                borderRadius: "12px",
                fontSize: "0.95rem",
                background: "rgba(255,255,255,0.05)",
                border: "1px solid rgba(255,255,255,0.18)",
