function FloatingEvaluation({ fieldCode, criteria, values, onChange }) {
    if (!criteria) return null;

    const nonDefault = criteria.filter(c => !c.defaultCriterion);

    const yesNo = nonDefault.filter(c => c.scaleType === "QUALITATIVE");
    const rating = nonDefault.filter(c => c.scaleType === "RATING");
    const numeric = nonDefault.filter(c => c.scaleType === "NUMERIC");
    const qual = nonDefault.filter(c => c.scaleType === "QUALITATIVE");

    return (
        <div style={{ marginTop: "25px", width: "100%" }}>
            <div
                style={{
                    display: "flex",
                    flexWrap: "wrap",
                    justifyContent: "center",
                    alignItems: "flex-start",
                    gap: "44px",
                    width: "100%",
                }}
            >

            {/* RATING */}
            {rating.map(c => (
                <div key={c.id} style={{
                    background: "rgba(255,255,255,0.05)",
                    padding: "18px 20px",
                    borderRadius: "16px",
                    border: "1px solid rgba(255,255,255,0.12)",
                    marginBottom: "18px",
                    boxShadow:
                        "0 0 20px rgba(0,0,0,0.35), inset 0 0 12px rgba(255,255,255,0.08)",
                    backdropFilter: "blur(6px)",
                    transition: "0.25s ease",
                }}
                     onMouseEnter={(e) => {
                         e.currentTarget.style.transform = "translateY(-2px)";
                         e.currentTarget.style.boxShadow =
                             "0 0 25px rgba(6,182,212,0.25), inset 0 0 12px rgba(255,255,255,0.12)";
                     }}
                     onMouseLeave={(e) => {
                         e.currentTarget.style.transform = "translateY(0)";
                         e.currentTarget.style.boxShadow =
                             "0 0 20px rgba(0,0,0,0.35), inset 0 0 12px rgba(255,255,255,0.08)";
                     }}>
                    <div style={{ fontWeight: "600", marginBottom: 4 }}>{c.name}</div>
                    <ModernRating
                        value={values?.[c.id] || 0}
                        onChange={(v) => onChange(c.id, v)}
                    />
                </div>
            ))}

            {/* NUMERIC */}
            {numeric.map(c => {
                const [min,max] = c.scaleRange.split("-");
                return (
                    <div key={c.id} style={{ marginBottom: 14, textAlign: "left" }}>
                        <div style={{ fontWeight: "600", marginBottom: 4 }}>
                            {c.name} ({c.scaleRange})
                        </div>
                        <ModernNumericInput
                            min={Number(min)}
                            max={Number(max)}
                            value={values?.[c.id] || ""}
                            onChange={(v) => onChange(c.id, v)}
                        />
                    </div>
                );
            })}

            {/* QUALITATIVE */}
            {qual.map(c => (
                <div key={c.id} style={{ marginBottom: 14, textAlign: "left" }}>
                    <div style={{ fontWeight: "600", marginBottom: 4 }}>{c.name}</div>
                    <QualitativeInput
                        value={values?.[c.id] || ""}
                        onChange={(v) => onChange(c.id, v)}
                    />
                </div>
            ))}
            </div>
        </div>
    );
}

function FloatingCustomCriteria({ fieldCode, criteria, values, onChange }) {
    if (!criteria) return null;

    const custom = criteria.filter(c => !c.defaultCriterion);

    if (custom.length === 0) return null;

    return (
        <div style={{ marginTop: 20, padding: 10 }}>
            <h4 style={{ textAlign: "left", marginBottom: 10 }}>
                Custom Criteria
            </h4>

            {custom.map(c => (
                <div key={c.id} style={{ marginBottom: 12, textAlign: "left" }}>
                    <div style={{ marginBottom: 4, fontWeight: 600 }}>{c.name}</div>

                    <input
                        type="text"
                        value={values[c.id] || ""}
                        onChange={(e) => onChange(c.id, e.target.value)}
                        placeholder="Enter value..."
                        style={{
                            width: "100%",
                            padding: "8px",
                            borderRadius: "8px",
                            background: "rgba(255,255,255,0.08)",
                            border: "1px solid rgba(255,255,255,0.2)",
                            color: "white"
                        }}
                    />
                </div>
            ))}
        </div>
    );
}
